+fn run_cache(args: &CacheArgs) {
+    if args.help {
+        print!("{CACHE_HELP}");
+        return;
+    }
+
+    if !args.build && !args.clear && !args.acknowledgements {
+        print!("{CACHE_HELP}");
+        std::process::exit(2);
+    }
+
+    let target = args.target.clone().unwrap_or_else(default_cache_dir);
+    if args.clear {
+        clear_cache_dir(&target);
+        return;
+    }
+    if args.build || args.acknowledgements {
+        build_cache(args.source.as_deref(), &target, args.acknowledgements);
+    }
+}
+
+fn clear_cache_dir(target: &Path) {
+    let themes_path = target.join("themes.bin");
+    let syntaxes_path = target.join("syntaxes.bin");
+    let metadata_path = target.join("metadata.yaml");
+    clear_cache_file("theme set cache", &themes_path);
+    clear_cache_file("syntax set cache", &syntaxes_path);
+    clear_cache_file("metadata file", &metadata_path);
+}
+
+fn clear_cache_file(label: &str, path: &Path) {
+    if path.exists() {
+        let _ = fs::remove_file(path);
+        println!("Clearing {label} ... okay");
+    } else {
+        println!("Clearing {label} ... skipped (not present)");
+    }
+}
+
+fn build_cache(source: Option<&Path>, target: &Path, acknowledgements_only: bool) {
+    let source_root = source.map(Path::to_path_buf).unwrap_or_else(default_config_dir);
+    let themes_dir = source_root.join("themes");
+    let syntaxes_dir = source_root.join("syntaxes");
+    let _ = fs::create_dir_all(target);
+
+    if !themes_dir.exists() {
+        println!(
+            "No themes were found in '{}', using the default set",
+            display_path(&themes_dir)
+        );
+    }
+    if !syntaxes_dir.exists() {
+        println!(
+            "No syntaxes were found in '{}', using the default set.",
+            display_path(&syntaxes_dir)
+        );
+    }
+
+    if acknowledgements_only {
+        let ack_path = target.join("acknowledgements.bin");
+        let _ = fs::write(&ack_path, ACKNOWLEDGEMENTS.as_bytes());
+        println!("Writing acknowledgements to {} ... okay", display_path(&ack_path));
+        return;
+    }
+
+    let themes_bin = target.join("themes.bin");
+    let syntaxes_bin = target.join("syntaxes.bin");
+    let metadata = target.join("metadata.yaml");
+
+    let _ = fs::write(&themes_bin, b"bat-cleanroom themes\n");
+    let _ = fs::write(&syntaxes_bin, b"bat-cleanroom syntaxes\n");
+    let _ = fs::write(
+        &metadata,
+        "created_by: bat-cleanroom\nversion: 0.26.1\n".as_bytes(),
+    );
+
+    println!("Writing theme set to {} ... okay", display_path(&themes_bin));
+    println!("Writing syntax set to {} ... okay", display_path(&syntaxes_bin));
+    println!("Writing metadata to folder {} ... okay", display_path(target));
+}
