+    let decorations_when = if cli.force_colorization {
+        When::Always
+    } else {
+        cli.decorations
+    };
+
+    let colorized = match color_when {
+        When::Always => true,
+        When::Never => false,
+        When::Auto => stdout_is_tty && env::var_os("NO_COLOR").is_none(),
+    };
+
+    let decorations_on = match decorations_when {
+        When::Always => true,
+        When::Never => false,
+        When::Auto => stdout_is_tty || color_when == When::Always,
+    };
+
+    let mut style = resolve_style(&cli.style);
+    if cli.plain > 0 {
+        style = StyleSet::plain();
+    }
+    if !decorations_on {
+        style = StyleSet::plain();
+    }
+
+    let wrap = if cli.chop_long_lines {
+        WrapMode::Never
+    } else if cli.wrap == WrapMode::Auto && !stdout_is_tty {
+        WrapMode::Never
+    } else {
+        cli.wrap
+    };
+
+    if colorized {
+        maybe_warn_unknown_theme(cli.theme.as_deref());
+    }
+
+    let terminal_width = resolve_terminal_width(cli.terminal_width.as_deref(), stdout_is_tty);
+    let highlight_ranges = parse_ranges(&cli.highlight_line).unwrap_or_default();
+    let line_ranges = parse_ranges(&cli.line_range).unwrap_or_default();
+    let map_syntax = cli
+        .map_syntax
+        .iter()
+        .filter_map(|raw| parse_map_syntax(raw))
+        .collect::<Vec<_>>();
+
+    let settings = Settings {
+        tabs,
+        colorized,
+        decorations_on,
+        style,
+        number_override: cli.number,
+        plain_override: cli.plain > 0,
+        wrap,
+        terminal_width,
+        highlight_ranges,
+        line_ranges,
+        diff: cli.diff,
+        diff_context: cli.diff_context,
+        binary: cli.binary,
+        show_all: cli.show_all,
+        nonprintable_notation: cli.nonprintable_notation,
+        quiet_empty: cli.quiet_empty,
+        syntax_language: cli.language.clone(),
+        fallback_syntax: cli.fallback_syntax.clone(),
+        file_name_override: cli.file_name.clone(),
+        ignored_suffix: cli.ignored_suffix.clone(),
+        strip_ansi: cli.strip_ansi,
+        map_syntax,
+    };
+
+    let mut files = cli.files.clone();
+    if files.is_empty() {
+        files.push("-".to_owned());
+    }
+
+    let ps = SyntaxSet::load_defaults_newlines();
+    let theme = load_theme();
+    let mut stdin_data: Option<Vec<u8>> = None;
+    let mut stdin_consumed = false;
+    let mut any_error = false;
+    let mut stdout = io::stdout().lock();
+
+    for file in files {
+        let source = match read_source(
+            &file,
+            settings.file_name_override.as_deref(),
+            &mut stdin_data,
+            &mut stdin_consumed,
+        ) {
+            Ok(data) => data,
+            Err(err) => {
+                eprint_error(&err);
+                any_error = true;
+                continue;
+            }
+        };
+
+        match render_source(&source, &settings, &ps, theme.as_ref(), stdin_is_tty) {
+            Ok(bytes) => {
+                if !bytes.is_empty() {
+                    let _ = stdout.write_all(&bytes);
+                }
+            }
+            Err(err) => {
+                eprint_error(&err);
+                any_error = true;
+            }
+        }
+    }
+
+    if any_error {
+        std::process::exit(1);
+    }
+}
+
+fn resolve_style(raw: &Option<String>) -> StyleSet {
+    match raw.as_deref() {
+        None => StyleSet::default_style(),
+        Some("default") => StyleSet::default_style(),
+        Some("auto") => StyleSet::default_style(),
+        Some("full") => StyleSet::full_style(),
+        Some("plain") => StyleSet::plain(),
+        Some(list) => {
+            let mut style = StyleSet::plain();
+            for item in list.split(',').map(str::trim).filter(|s| !s.is_empty()) {
+                match item {
+                    "changes" => style.changes = true,
+                    "header" | "header-filename" => style.header_filename = true,
+                    "header-filesize" => style.header_filesize = true,
+                    "grid" => style.grid = true,
+                    "rule" => style.rule = true,
+                    "numbers" => style.numbers = true,
+                    "snip" => style.snip = true,
+                    _ => {}
+                }
+            }
+            style
+        }
+    }
+}
+
+fn resolve_terminal_width(raw: Option<&str>, stdout_is_tty: bool) -> usize {
+    let base = if stdout_is_tty {
+        terminal_size()
+            .map(|(Width(width), _)| width as usize)
+            .unwrap_or(80)
+    } else {
+        80
+    };
+
+    let Some(raw) = raw else {
+        return base.max(20);
+    };
+
+    if let Some(rest) = raw.strip_prefix('+') {
+        return base.saturating_add(rest.parse::<usize>().unwrap_or(0)).max(20);
+    }
+    if let Some(rest) = raw.strip_prefix('-') {
+        return base.saturating_sub(rest.parse::<usize>().unwrap_or(0)).max(20);
+    }
+    raw.parse::<usize>().unwrap_or(base).max(20)
+}
