+                &mut keep_lines,
+                &mut markers,
+                &mut emitted_in_hunk,
+                &mut mark_next_overline,
+            );
+            in_hunk = true;
+            emitted_in_hunk.clear();
+            mark_next_overline = false;
+            if let Some(new_part) = rest.split_whitespace().nth(1) {
+                if let Some(new_range) = new_part.strip_prefix('+') {
+                    let start = new_range
+                        .split(',')
+                        .next()
+                        .unwrap_or("1")
+                        .parse::<usize>()
+                        .unwrap_or(1);
+                    current_new = start;
+                }
+            }
+            continue;
+        }
+        if !in_hunk {
+            continue;
+        }
+        if line.starts_with("---") || line.starts_with("+++") {
+            continue;
+        }
+        if line.starts_with('\\') {
+            continue;
+        }
+        let prefix = line.chars().next().unwrap_or(' ');
+        let content = line[1..].to_owned();
+        if prefix == ' ' {
+            finalize_diff_block(
+                &mut pending_block,
+                &mut current_new,
+                &mut keep_lines,
+                &mut markers,
+                &mut emitted_in_hunk,
+                &mut mark_next_overline,
+            );
+            keep_lines.insert(current_new);
