fn pre_scan(raw_args: &[OsString]) -> Option<EarlyAction> {
    let mut first_non_option: Option<String> = None;
    let mut after_double_dash = false;
    let mut saw_short_help = false;
    let mut saw_long_help = false;
    let mut saw_version = false;

    for arg in raw_args.iter().skip(1) {
        let Some(arg) = arg.to_str() else {
            continue;
        };
        if after_double_dash {
            break;
        }
        if arg == "--" {
            after_double_dash = true;
            continue;
        }
        if first_non_option.is_none() && !arg.starts_with('-') {
            first_non_option = Some(arg.to_owned());
            if arg == "cache" {
                continue;
            }
        }
        if first_non_option.as_deref() == Some("cache") {
            if arg == "-h" || arg == "--help" {
                return Some(EarlyAction::CacheHelp);
            }
            continue;
        }
        if arg == "-h" {
            saw_short_help = true;
        } else if arg == "--help" {
            saw_long_help = true;
        } else if arg == "-V" || arg == "--version" {
            saw_version = true;
        }
    }

    if saw_long_help {
        Some(EarlyAction::RootLongHelp)
    } else if saw_short_help {
        Some(EarlyAction::RootShortHelp)
    } else if saw_version {
        Some(EarlyAction::RootVersion)
    } else {
        None
    }
}

fn handle_early_action(action: EarlyAction) {
    match action {
        EarlyAction::RootShortHelp => print!("{SHORT_HELP}"),
        EarlyAction::RootLongHelp => print!("{LONG_HELP}"),
        EarlyAction::RootVersion => print!("{VERSION_OUTPUT}"),
        EarlyAction::CacheHelp => print!("{CACHE_HELP}"),
    }
}

fn run_cache(args: &CacheArgs) {
    if args.help {
        print!("{CACHE_HELP}");
        return;
    }

    if !args.build && !args.clear && !args.acknowledgements {
        print!("{CACHE_HELP}");
        std::process::exit(2);
    }

    let target = args.target.clone().unwrap_or_else(default_cache_dir);
    if args.clear {
        clear_cache_dir(&target);
        return;
    }
    if args.build || args.acknowledgements {
        build_cache(args.source.as_deref(), &target, args.acknowledgements);
    }
}

fn clear_cache_dir(target: &Path) {
    let themes_path = target.join("themes.bin");
    let syntaxes_path = target.join("syntaxes.bin");
    let metadata_path = target.join("metadata.yaml");
    clear_cache_file("theme set cache", &themes_path);
    clear_cache_file("syntax set cache", &syntaxes_path);
    clear_cache_file("metadata file", &metadata_path);
}

fn clear_cache_file(label: &str, path: &Path) {
    if path.exists() {
        let _ = fs::remove_file(path);
        println!("Clearing {label} ... okay");
    } else {
        println!("Clearing {label} ... skipped (not present)");
    }
}

fn build_cache(source: Option<&Path>, target: &Path, acknowledgements_only: bool) {
    let source_root = source.map(Path::to_path_buf).unwrap_or_else(default_config_dir);
    let themes_dir = source_root.join("themes");
    let syntaxes_dir = source_root.join("syntaxes");
    let _ = fs::create_dir_all(target);

    if !themes_dir.exists() {
        println!(
            "No themes were found in '{}', using the default set",
            display_path(&themes_dir)
        );
    }
    if !syntaxes_dir.exists() {
        println!(
            "No syntaxes were found in '{}', using the default set.",
            display_path(&syntaxes_dir)
        );
    }

    if acknowledgements_only {
        let ack_path = target.join("acknowledgements.bin");
        let _ = fs::write(&ack_path, ACKNOWLEDGEMENTS.as_bytes());
        println!("Writing acknowledgements to {} ... okay", display_path(&ack_path));
        return;
    }

    let themes_bin = target.join("themes.bin");
    let syntaxes_bin = target.join("syntaxes.bin");
    let metadata = target.join("metadata.yaml");

    let _ = fs::write(&themes_bin, b"bat-cleanroom themes\n");
    let _ = fs::write(&syntaxes_bin, b"bat-cleanroom syntaxes\n");
    let _ = fs::write(
        &metadata,
        "created_by: bat-cleanroom\nversion: 0.26.1\n".as_bytes(),
    );

    println!("Writing theme set to {} ... okay", display_path(&themes_bin));
    println!("Writing syntax set to {} ... okay", display_path(&syntaxes_bin));
    println!("Writing metadata to folder {} ... okay", display_path(target));
}

fn run_main(cli: Cli) {
    let stdout_is_tty = io::stdout().is_terminal();
    let stdin_is_tty = io::stdin().is_terminal();
    let tabs = cli.tabs.unwrap_or_else(default_tabs);

    let color_when = if cli.force_colorization { When::Always } else { cli.color };
    let decorations_when = if cli.force_colorization {
        When::Always
    } else {
        cli.decorations
    };

    let colorized = match color_when {
        When::Always => true,
        When::Never => false,
        When::Auto => stdout_is_tty && env::var_os("NO_COLOR").is_none(),
    };

    let decorations_on = match decorations_when {
        When::Always => true,
        When::Never => false,
        When::Auto => stdout_is_tty || color_when == When::Always,
    };

    let mut style = resolve_style(&cli.style);
    if cli.plain > 0 {
        style = StyleSet::plain();
    }
    if !decorations_on {
        style = StyleSet::plain();
    }

    let wrap = if cli.chop_long_lines {
        WrapMode::Never
    } else if cli.wrap == WrapMode::Auto && !stdout_is_tty {
        WrapMode::Never
    } else {
        cli.wrap
    };

    if colorized {
        maybe_warn_unknown_theme(cli.theme.as_deref());
    }

    let terminal_width = resolve_terminal_width(cli.terminal_width.as_deref(), stdout_is_tty);
    let highlight_ranges = parse_ranges(&cli.highlight_line).unwrap_or_default();
    let line_ranges = parse_ranges(&cli.line_range).unwrap_or_default();
    let map_syntax = cli
        .map_syntax
        .iter()
        .filter_map(|raw| parse_map_syntax(raw))
        .collect::<Vec<_>>();

    let settings = Settings {
        tabs,
        colorized,
        decorations_on,
        style,
        number_override: cli.number,
        plain_override: cli.plain > 0,
        wrap,
        terminal_width,
        highlight_ranges,
        line_ranges,
        diff: cli.diff,
        diff_context: cli.diff_context,
        binary: cli.binary,
        show_all: cli.show_all,
        nonprintable_notation: cli.nonprintable_notation,
        quiet_empty: cli.quiet_empty,
        syntax_language: cli.language.clone(),
        fallback_syntax: cli.fallback_syntax.clone(),
        file_name_override: cli.file_name.clone(),
        ignored_suffix: cli.ignored_suffix.clone(),
        strip_ansi: cli.strip_ansi,
        map_syntax,
    };

    let mut files = cli.files.clone();
    if files.is_empty() {
        files.push("-".to_owned());
    }

    let ps = SyntaxSet::load_defaults_newlines();
    let theme = load_theme();
    let mut stdin_data: Option<Vec<u8>> = None;
    let mut stdin_consumed = false;
    let mut any_error = false;
    let mut stdout = io::stdout().lock();

    for file in files {
        let source = match read_source(
            &file,
            settings.file_name_override.as_deref(),
            &mut stdin_data,
            &mut stdin_consumed,
        ) {
            Ok(data) => data,
            Err(err) => {
                eprint_error(&err);
                any_error = true;
                continue;
            }
        };

        match render_source(&source, &settings, &ps, theme.as_ref(), stdin_is_tty) {
            Ok(bytes) => {
                if !bytes.is_empty() {
                    let _ = stdout.write_all(&bytes);
                }
            }
            Err(err) => {
                eprint_error(&err);
                any_error = true;
            }
        }
    }

    if any_error {
        std::process::exit(1);
    }
}

fn resolve_style(raw: &Option<String>) -> StyleSet {
    match raw.as_deref() {
        None => StyleSet::default_style(),
        Some("default") => StyleSet::default_style(),
        Some("auto") => StyleSet::default_style(),
        Some("full") => StyleSet::full_style(),
        Some("plain") => StyleSet::plain(),
        Some(list) => {
            let mut style = StyleSet::plain();
            for item in list.split(',').map(str::trim).filter(|s| !s.is_empty()) {
                match item {
                    "changes" => style.changes = true,
                    "header" | "header-filename" => style.header_filename = true,
                    "header-filesize" => style.header_filesize = true,
                    "grid" => style.grid = true,
                    "rule" => style.rule = true,
                    "numbers" => style.numbers = true,
                    "snip" => style.snip = true,
                    _ => {}
                }
            }
            style
        }
    }
}

fn resolve_terminal_width(raw: Option<&str>, stdout_is_tty: bool) -> usize {
    let base = if stdout_is_tty {
        terminal_size()
            .map(|(Width(width), _)| width as usize)
            .unwrap_or(80)
    } else {
        80
    };

    let Some(raw) = raw else {
        return base.max(20);
    };

    if let Some(rest) = raw.strip_prefix('+') {
        return base.saturating_add(rest.parse::<usize>().unwrap_or(0)).max(20);
    }
    if let Some(rest) = raw.strip_prefix('-') {
        return base.saturating_sub(rest.parse::<usize>().unwrap_or(0)).max(20);
    }
    raw.parse::<usize>().unwrap_or(base).max(20)
}

fn parse_map_syntax(raw: &str) -> Option<MapSyntaxEntry> {
    let (glob, syntax) = raw.split_once(':')?;
    Some(MapSyntaxEntry {
        raw: raw.to_owned(),
        glob: glob.to_owned(),
        syntax: syntax.to_owned(),
    })
}

fn parse_ranges(raw_ranges: &[String]) -> Result<Vec<ResolvedRange>, String> {
    let mut result = Vec::new();
    for raw in raw_ranges {
        let range = parse_range_spec(raw)?;
        result.push(range);
    }
    Ok(result)
}

fn parse_range_spec(raw: &str) -> Result<ResolvedRange, String> {
    if !raw.contains(':') {
        let n: usize = raw.parse::<usize>().map_err(|e| e.to_string())?;
        return Ok(ResolvedRange { start: n, end: n });
    }

    let parts = raw.split(':').collect::<Vec<_>>();
    if parts.len() < 2 || parts.len() > 3 {
        return Err("invalid line range".to_owned());
    }

    let start_raw = parts[0];
    let middle_raw = parts[1];
    let context_raw = if parts.len() == 3 { Some(parts[2]) } else { None };

    if middle_raw.is_empty() && context_raw.is_some() {
        let center = parse_signed_usize(start_raw)?;
        let context = parse_signed_usize(context_raw.unwrap())?;
        let start = center.saturating_sub(context as usize);
        let end = center.saturating_add(context as usize);
        return Ok(ResolvedRange { start, end });
    }

    let mut start = if start_raw.is_empty() {
        1
    } else if start_raw.starts_with('-') {
        0
    } else {
        start_raw.parse::<usize>().map_err(|e| e.to_string())?
    };

    let mut end = if middle_raw.is_empty() {
        usize::MAX
    } else if let Some(offset) = middle_raw.strip_prefix('+') {
        let plus = offset.parse::<usize>().map_err(|e| e.to_string())?;
        start.saturating_add(plus)
    } else {
        middle_raw.parse::<usize>().map_err(|e| e.to_string())?
    };

    if let Some(raw_context) = context_raw {
        let ctx = raw_context.parse::<usize>().map_err(|e| e.to_string())?;
        start = start.saturating_sub(ctx);
        end = end.saturating_add(ctx);
    }

    Ok(ResolvedRange { start, end })
}

fn parse_signed_usize(raw: &str) -> Result<isize, String> {
    raw.parse::<isize>().map_err(|e| e.to_string())
}

fn apply_ranges(total_lines: usize, requested: &[ResolvedRange]) -> Vec<ResolvedRange> {
    if requested.is_empty() {
        return vec![ResolvedRange {
            start: 1,
            end: total_lines,
        }];
    }

    let mut normalized = Vec::new();
    for range in requested {
        let mut start = range.start;
        let mut end = range.end;
        if start == 0 {
            start = 1;
        }
        if end == usize::MAX {
            end = total_lines;
        }
        if start > total_lines && range.start == 0 {
            start = 1;
        }
        if end > total_lines {
            end = total_lines;
        }
        if start > end || end == 0 {
            continue;
        }
        normalized.push(ResolvedRange { start, end });
    }
    normalized.sort_by_key(|r| (r.start, r.end));
    let mut merged = Vec::new();
    for range in normalized {
        if let Some(last) = merged.last_mut() {
            if range.start <= last.end.saturating_add(1) {
                last.end = max(last.end, range.end);
                continue;
            }
        }
        merged.push(range);
    }
    merged
}

fn default_tabs() -> usize {
    env::var("BAT_TABS")
        .ok()
        .and_then(|v| v.parse::<usize>().ok())
        .unwrap_or(4)
}

fn default_config_dir() -> PathBuf {
    let mut root = config_dir()
        .or_else(|| home_dir().map(|h| h.join(".config")))
        .unwrap_or_else(|| PathBuf::from("."));
    root.push("bat");
    root
}

fn default_cache_dir() -> PathBuf {
    if let Some(custom) = env::var_os("BAT_CACHE_PATH") {
        return PathBuf::from(custom);
    }
    let mut root = cache_dir()
        .or_else(|| home_dir().map(|h| h.join(".cache")))
        .unwrap_or_else(|| PathBuf::from("."));
    root.push("bat");
    root
}

fn default_config_file() -> PathBuf {
    if let Some(custom) = env::var_os("BAT_CONFIG_PATH") {
        return PathBuf::from(custom);
    }
    default_config_dir().join("config")
}

fn display_path(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

fn generate_config_file() {
    let path = default_config_file();
    if path.exists() {
        print!("A config file already exists at: {}\nOverwrite? (y/N): ", display_path(&path));
        let _ = io::stdout().flush();
        let mut input = String::new();
        let _ = io::stdin().read_line(&mut input);
        let decision = input.trim().eq_ignore_ascii_case("y");
        if !decision {
            return;
        }
    }

    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let _ = fs::write(&path, CONFIG_TEMPLATE.as_bytes());
    println!("Success! Config file written to {}", display_path(&path));
}

fn build_diagnostic(raw_args: &[OsString]) -> String {
    let mut out = String::new();
    out.push_str("#### Software version\n\n");
    out.push_str(VERSION_OUTPUT);
    out.push('\n');

    out.push_str("#### Operating system\n\n");
    out.push_str(&format!(
        "- OS: {}\n",
        detect_os_name().unwrap_or_else(|| "Linux".to_owned())
    ));
    out.push_str(&format!(
        "- Kernel: {}\n\n",
        detect_kernel().unwrap_or_else(|| "unknown".to_owned())
    ));

    out.push_str("#### Command-line\n\n```bash\n");
    let cmdline = raw_args
        .iter()
        .filter_map(|arg| arg.to_str())
        .collect::<Vec<_>>()
        .join(" ");
    out.push_str(&cmdline);
    out.push_str(" \n```\n\n");

    out.push_str("#### Environment variables\n\n```bash\n");
    for key in [
        "BAT_CACHE_PATH",
        "BAT_CONFIG_PATH",
        "BAT_OPTS",
        "BAT_PAGER",
        "BAT_PAGING",
        "BAT_STYLE",
        "BAT_TABS",
        "BAT_THEME",
        "BAT_WIDTH",
        "BAT_THEME_DARK",
        "BAT_THEME_LIGHT",
        "COLORTERM",
        "LANG",
        "LC_ALL",
        "LESS",
        "MANPAGER",
        "NO_COLOR",
        "PAGER",
        "SHELL",
        "TERM",
        "XDG_CACHE_HOME",
        "XDG_CONFIG_HOME",
    ] {
        let value = env::var(key)
            .map(|v| {
                if v.is_empty() {
                    "''".to_owned()
                } else {
                    v
                }
            })
            .unwrap_or_else(|_| "<not set>".to_owned());
        out.push_str(&format!("{key}={value}\n"));
    }
    out.push_str("```\n\n");

    out.push_str("#### System Config file\n\n");
    out.push_str(&diagnostic_file_section(&PathBuf::from("/etc/bat/config")));
    out.push('\n');

    out.push_str("#### Config file\n\n");
    out.push_str(&diagnostic_file_section(&default_config_file()));
    out.push('\n');

    out.push_str("#### Custom assets metadata\n\n");
    out.push_str(&diagnostic_file_section(&default_cache_dir().join("metadata.yaml")));
    out.push('\n');

    out.push_str("#### Custom assets\n\n");
    if default_cache_dir().exists() {
        out.push_str(&format!("'{}' exists\n\n", display_path(&default_cache_dir())));
    } else {
        out.push_str(&format!("'{}' not found\n\n", display_path(&default_cache_dir())));
    }

    out.push_str("#### Detected terminal color scheme\n\nnot detected\n\n");
    out.push_str("#### Compile time information\n\n");
    out.push_str("- Profile: release\n");
    out.push_str("- Target triple: x86_64-unknown-linux-gnu\n");
    out.push_str("- Family: unix\n");
    out.push_str("- OS: linux\n");
    out.push_str("- Architecture: x86_64\n");
    out.push_str("- Pointer width: 64\n");
    out.push_str("- Endian: little\n");
    out.push_str("- CPU features: fxsr,sse,sse2\n");
    out.push_str("- Host: x86_64-unknown-linux-gnu\n\n");

    out.push_str("#### Less version\n\n```\n");
    let pager = env::var("BAT_PAGER")
        .ok()
        .or_else(|| env::var("PAGER").ok())
        .unwrap_or_else(|| "less".to_owned());
    let pager_parts = shell_split(&pager).unwrap_or_else(|_| vec![pager.clone()]);
    if let Some(program) = pager_parts.first() {
        let output = Command::new(program)
            .args(pager_parts.iter().skip(1))
            .arg("--version")
            .output();
        match output {
            Ok(output) => {
                out.push_str(&format!("> {} --version \n", pager));
                out.push_str(&String::from_utf8_lossy(&output.stdout));
            }
            Err(_) => {
                out.push_str(&format!("> {} --version \n<unavailable>\n", pager));
            }
        }
    }
    out.push_str("```\n\n");
    out
}

fn diagnostic_file_section(path: &Path) -> String {
    match fs::read_to_string(path) {
        Ok(contents) => format!("```text\n{contents}```\n"),
        Err(err) => format!("Could not read contents of '{}': {err}.\n", display_path(path)),
    }
}

fn detect_kernel() -> Option<String> {
    let output = Command::new("uname").arg("-r").output().ok()?;
    let text = String::from_utf8(output.stdout).ok()?;
    Some(text.trim().to_owned())
}

fn detect_os_name() -> Option<String> {
    let text = fs::read_to_string("/etc/os-release").ok()?;
    for line in text.lines() {
        if let Some(value) = line.strip_prefix("PRETTY_NAME=") {
            return Some(value.trim_matches('"').to_owned());
        }
    }
    None
}

fn maybe_warn_unknown_theme(theme: Option<&str>) {
    let Some(theme) = theme else {
        return;
    };
    let known = known_theme_names();
    let special = matches!(
        theme,
        "auto" | "dark" | "light" | "auto:always" | "auto:system"
    );
    if special || known.contains(theme) {
        return;
    }
    eprint_warning(&format!("Unknown theme '{theme}', using default."));
}

fn known_theme_names() -> HashSet<&'static str> {
    LIST_THEMES.lines().collect::<HashSet<_>>()
}

fn read_source(
    file: &str,
    file_name_override: Option<&str>,
    stdin_data: &mut Option<Vec<u8>>,
    stdin_consumed: &mut bool,
) -> Result<SourceData, String> {
    if file == "-" {
        let bytes = if *stdin_consumed {
            Vec::new()
        } else if let Some(existing) = stdin_data.take() {
            *stdin_consumed = true;
            existing
        } else {
            let mut bytes = Vec::new();
            io::stdin()
                .read_to_end(&mut bytes)
                .map_err(|e| format!("stdin: {e}"))?;
            *stdin_consumed = true;
            bytes
        };
        let label = file_name_override.unwrap_or("STDIN").to_owned();
        return Ok(SourceData {
            label,
            actual_path: None,
            bytes,
            is_stdin: true,
        });
    }

    let path = PathBuf::from(file);
    if path.is_dir() {
        return Err(format!("'{}' is a directory.", display_path(&path)));
    }
    let bytes = fs::read(&path)
        .map_err(|e| format!("'{}': {e}", display_path(&path)))?;
    let label = file_name_override.unwrap_or(file).to_owned();
    Ok(SourceData {
        label,
        actual_path: Some(path),
        bytes,
        is_stdin: false,
    })
}

fn render_source(
    source: &SourceData,
    settings: &Settings,
    ps: &SyntaxSet,
    theme: Option<&Theme>,
    stdin_is_tty: bool,
) -> Result<Vec<u8>, String> {
    let is_binary = source.bytes.iter().any(|b| *b == 0);
    if settings.quiet_empty && source.bytes.is_empty() {
        return Ok(Vec::new());
    }

    let has_header_layout = settings.style.has_header();
    let has_table_layout = settings.style.grid && (settings.style.numbers || settings.style.has_header());
    let raw_passthrough = !settings.show_all
        && !settings.number_override
        && settings.style.is_empty()
        && !settings.plain_override
        && !settings.diff
        && settings.line_ranges.is_empty()
        && !settings.squeeze_blank
        && settings.squeeze_limit.is_none()
        && !settings.colorized
        && !has_header_layout
        && settings.binary == BinaryBehavior::NoPrinting;

    if raw_passthrough {
        return Ok(source.bytes.clone());
    }

    if is_binary && settings.binary == BinaryBehavior::NoPrinting && !settings.show_all {
        if has_header_layout {
            return Ok(render_binary_header_only(source, settings, "<BINARY>"));
        }
        return Ok(render_binary_warning(source));
    }

    if source.bytes.is_empty() && has_header_layout {
        return Ok(render_binary_header_only(source, settings, "<EMPTY>"));
    }

    let mut lines = split_lines(&source.bytes);
    if settings.strip_ansi != When::Never {
        strip_ansi_lines(&mut lines, settings.strip_ansi, settings.syntax_language.as_deref());
    }

    if settings.squeeze_blank || settings.squeeze_limit.is_some() {
        let limit = settings.squeeze_limit.unwrap_or(1);
        lines = squeeze_blank_lines(lines, limit);
    }

    let diff_markers = if settings.diff {
        git_diff_markers(source, settings.diff_context)?
    } else {
        None
    };

    let filtered_lines = if let Some(markers) = diff_markers {
        if markers.is_empty() {
            return Ok(Vec::new());
        }
        apply_diff_filter(lines, &markers)
    } else {
        apply_line_range_filter(lines, &settings.line_ranges)?
    };

    let mut display_lines = build_display_lines(filtered_lines, settings);
    if display_lines.is_empty() && settings.quiet_empty {
        return Ok(Vec::new());
    }

    let syntax = resolve_syntax(source, settings, ps, &display_lines)?;
    let output = render_display_lines(source, &display_lines, settings, syntax, ps, theme, is_binary, stdin_is_tty);
    Ok(output)
}

fn render_binary_header_only(source: &SourceData, settings: &Settings, tag: &str) -> Vec<u8> {
    if settings.style.has_header() {
        render_header_only(source, settings, tag)
    } else {
        Vec::new()
    }
}

fn render_binary_warning(source: &SourceData) -> Vec<u8> {
    format!(
        "\x1b[33m[bat warning]\x1b[0m: Binary content from file '{}' will not be printed to the terminal (but will be present if the output of 'bat' is piped). You can use 'bat -A' to show the binary file contents.\n",
        source.label
    )
    .into_bytes()
}

fn split_lines(bytes: &[u8]) -> Vec<RawLine> {
    if bytes.is_empty() {
        return Vec::new();
    }
    let mut lines = Vec::new();
    let mut start = 0;
    let mut line_number = 1;
    for (index, byte) in bytes.iter().enumerate() {
        if *byte == b'\n' {
            lines.push(RawLine {
                number: line_number,
                bytes: bytes[start..index].to_vec(),
                had_newline: true,
            });
            line_number += 1;
            start = index + 1;
        }
    }
    if start < bytes.len() {
        lines.push(RawLine {
            number: line_number,
            bytes: bytes[start..].to_vec(),
            had_newline: false,
        });
    }
    lines
}

fn strip_ansi_lines(lines: &mut [RawLine], mode: When, syntax_language: Option<&str>) {
    let should_strip = match mode {
        When::Always => true,
        When::Never => false,
        When::Auto => !matches!(syntax_language, Some("plain") | Some("txt") | Some("text")),
    };
    if !should_strip {
        return;
    }
    let regex = Regex::new(r"\x1B\[[0-?]*[ -/]*[@-~]").unwrap();
    for line in lines {
        let text = String::from_utf8_lossy(&line.bytes);
        let stripped = regex.replace_all(&text, "");
        line.bytes = stripped.into_owned().into_bytes();
    }
}

fn squeeze_blank_lines(lines: Vec<RawLine>, limit: usize) -> Vec<RawLine> {
    let mut result = Vec::new();
    let mut blank_run = 0;
    for line in lines {
        if line.bytes.is_empty() {
            blank_run += 1;
            if blank_run > limit {
                continue;
            }
        } else {
            blank_run = 0;
        }
        result.push(line);
    }
    result
}

fn apply_line_range_filter(lines: Vec<RawLine>, requested: &[ResolvedRange]) -> Result<Vec<RawLine>, String> {
    if requested.is_empty() {
        return Ok(lines);
    }
    let total = lines.len();
    let ranges = resolve_requested_ranges(total, requested)?;
    let keep = ranges
        .iter()
        .flat_map(|range| range.start..=range.end)
        .collect::<BTreeSet<_>>();
    Ok(lines
        .into_iter()
        .filter(|line| keep.contains(&line.number))
        .collect())
}

fn resolve_requested_ranges(total: usize, requested: &[ResolvedRange]) -> Result<Vec<ResolvedRange>, String> {
    let mut resolved = Vec::new();
    for range in requested {
        let mut start = range.start;
        let mut end = range.end;
        if start == 0 {
            let last = range.end.min(total);
            start = total.saturating_sub(last).saturating_add(1);
            end = total;
        }
        if end == usize::MAX {
            end = total;
        }
        start = start.max(1);
        end = end.min(total);
        if start > end {
            continue;
        }
        resolved.push(ResolvedRange { start, end });
    }
    Ok(apply_ranges(total, &resolved))
}

fn build_display_lines(lines: Vec<RawLine>, settings: &Settings) -> Vec<DisplayLine> {
    let mut display = Vec::new();
    let ranges = if settings.diff {
        contiguous_ranges_from_lines(&lines)
    } else if settings.line_ranges.is_empty() {
        contiguous_ranges_from_lines(&lines)
    } else {
        contiguous_ranges_from_lines(&lines)
    };

    let line_lookup = lines
        .iter()
        .map(|line| (line.number, line))
        .collect::<std::collections::BTreeMap<_, _>>();

    let mut first_range = true;
    for range in ranges {
        if !first_range && settings.style.snip && !settings.number_override && settings.style.grid {
            display.push(DisplayLine {
                number: 0,
                text: String::new(),
                had_newline: true,
                marker: ' ',
                is_snip: true,
            });
        }
        first_range = false;
        for number in range.start..=range.end {
            if let Some(line) = line_lookup.get(&number) {
                display.push(DisplayLine {
                    number: line.number,
                    text: decode_line(line, settings),
                    had_newline: line.had_newline,
                    marker: ' ',
                    is_snip: false,
                });
            }
        }
    }

    if display.is_empty() {
        for line in lines {
            display.push(DisplayLine {
                number: line.number,
                text: decode_line(&line, settings),
                had_newline: line.had_newline,
                marker: ' ',
                is_snip: false,
            });
        }
    }
    display
}

fn contiguous_ranges_from_lines(lines: &[RawLine]) -> Vec<ResolvedRange> {
    let mut ranges = Vec::new();
    let mut start: Option<usize> = None;
    let mut prev = 0usize;
    for line in lines {
        match start {
            None => {
                start = Some(line.number);
                prev = line.number;
            }
            Some(s) => {
                if line.number == prev + 1 {
                    prev = line.number;
                } else {
                    ranges.push(ResolvedRange { start: s, end: prev });
                    start = Some(line.number);
                    prev = line.number;
                }
            }
        }
    }
    if let Some(s) = start {
        ranges.push(ResolvedRange { start: s, end: prev });
    }
    ranges
}

fn decode_line(line: &RawLine, settings: &Settings) -> String {
    if settings.show_all {
        render_show_all(line, settings.tabs, settings.nonprintable_notation)
    } else {
        String::from_utf8_lossy(&line.bytes).into_owned()
    }
}

fn render_show_all(line: &RawLine, tabs: usize, notation: NonPrintableNotation) -> String {
    let mut out = String::new();
    let mut column = 0usize;
    let text = String::from_utf8_lossy(&line.bytes);
    for ch in text.chars() {
        match ch {
            ' ' => {
                out.push('·');
                column += 1;
            }
            '\t' => {
                let tab_piece = render_tab_placeholder(column, tabs);
                out.push_str(&tab_piece);
                if tabs == 0 {
                    column += 1;
                } else {
                    let advance = tabs - (column % tabs);
                    column += advance;
                }
            }
            c if c.is_ascii() && !c.is_ascii_control() => {
                out.push(c);
                column += 1;
            }
            c if c.is_ascii_control() => {
                out.push_str(&control_notation(c as u8, notation));
                column += 1;
            }
            c => {
                out.push_str(&format!("\\u{{{:x}}}", c as u32));
                column += UnicodeWidthChar::width(c).unwrap_or(1);
            }
        }
    }
    if line.had_newline {
        out.push_str(match notation {
            NonPrintableNotation::Unicode => "␊",
            NonPrintableNotation::Caret => "^J",
        });
    }
    out
}

fn render_tab_placeholder(column: usize, tabs: usize) -> String {
    if tabs == 0 {
        return "├─┤".to_owned();
    }
    let advance = tabs - (column % tabs);
    match advance {
        0 | 1 => "↹".to_owned(),
        2 => "├┤".to_owned(),
        n => format!("├{}┤", "─".repeat(n - 2)),
    }
}

fn control_notation(byte: u8, notation: NonPrintableNotation) -> String {
    match notation {
        NonPrintableNotation::Unicode => match byte {
            0x7f => "␡".to_owned(),
            _ => char::from_u32(0x2400 + byte as u32)
                .unwrap_or('�')
                .to_string(),
        },
        NonPrintableNotation::Caret => match byte {
            b'\n' => "^J".to_owned(),
            b'\r' => "^M".to_owned(),
            b'\t' => "^I".to_owned(),
            0x7f => "^?".to_owned(),
            _ => format!("^{}", (byte + 64) as char),
        },
    }
}

fn resolve_syntax<'a>(
    source: &SourceData,
    settings: &Settings,
    ps: &'a SyntaxSet,
    display_lines: &[DisplayLine],
) -> Result<Option<&'a SyntaxReference>, String> {
    if !settings.colorized {
        return Ok(None);
    }

    if let Some(language) = settings.syntax_language.as_deref() {
        if let Some(syntax) = find_syntax_by_token(ps, language) {
            return Ok(Some(syntax));
        }
        return Err(format!("unknown syntax: '{language}'"));
    }

    for mapping in &settings.map_syntax {
        if path_matches(&mapping.glob, &source.label) {
            if let Some(syntax) = find_syntax_by_token(ps, &mapping.syntax) {
                return Ok(Some(syntax));
            }
        }
    }

    if let Some(path) = source.actual_path.as_ref() {
        if let Ok(Some(syntax)) = ps.find_syntax_for_file(path) {
            return Ok(Some(syntax));
        }
    }

    let detection_name = ignored_suffix_name(&source.label, settings.ignored_suffix.as_deref());
    if let Some(ext) = Path::new(&detection_name)
        .extension()
        .and_then(|ext| ext.to_str())
        .and_then(|ext| find_syntax_by_token(ps, ext))
    {
        return Ok(Some(ext));
    }

    if let Some(first) = display_lines.first() {
        if let Some(syntax) = ps.find_syntax_by_first_line(&first.text) {
            return Ok(Some(syntax));
        }
    }

    if let Some(fallback) = settings.fallback_syntax.as_deref() {
        if let Some(syntax) = find_syntax_by_token(ps, fallback) {
            return Ok(Some(syntax));
        }
    }

    Ok(None)
}

fn ignored_suffix_name(name: &str, ignored_suffix: Option<&str>) -> String {
    if let Some(suffix) = ignored_suffix {
        if let Some(stripped) = name.strip_suffix(suffix) {
            return stripped.to_owned();
        }
    }
    name.to_owned()
}

fn find_syntax_by_token<'a>(ps: &'a SyntaxSet, token: &str) -> Option<&'a SyntaxReference> {
    ps.find_syntax_by_name(token)
        .or_else(|| ps.find_syntax_by_token(token))
        .or_else(|| ps.find_syntax_by_extension(token))
}

fn path_matches(glob: &str, label: &str) -> bool {
    let mut builder = GlobSetBuilder::new();
    let Ok(compiled) = Glob::new(glob) else {
        return false;
    };
    builder.add(compiled);
    let Ok(set) = builder.build() else {
        return false;
    };
    set.is_match(label)
}

fn render_display_lines(
    source: &SourceData,
    display_lines: &[DisplayLine],
    settings: &Settings,
    syntax: Option<&SyntaxReference>,
    ps: &SyntaxSet,
    theme: Option<&Theme>,
    is_binary: bool,
    _stdin_is_tty: bool,
) -> Vec<u8> {
    let mut rendered = String::new();
    let line_count_width = display_lines
        .iter()
        .filter(|line| !line.is_snip)
        .map(|line| line.number.to_string().len())
        .max()
        .unwrap_or(1);

    let header_lines = build_header_lines(source, settings, is_binary);
    let has_table = settings.style.grid && (settings.style.numbers || settings.style.has_header());
    let number_width = if settings.diff {
        max(4, line_count_width) + 3
    } else {
        max(4, line_count_width) + 1
    };
    let right_width = settings
        .terminal_width
        .saturating_sub(if has_table { number_width + 1 } else { 0 })
        .max(1);
    let content_width = if has_table { right_width.saturating_sub(1) } else { right_width };

    if has_table {
        rendered.push_str(&table_rule(number_width, right_width, '┬', settings.colorized));
        rendered.push('\n');
        for header in header_lines {
            for piece in wrap_header(&header, content_width) {
                rendered.push_str(&format_table_header(number_width, &piece, settings.colorized));
                rendered.push('\n');
            }
        }
        rendered.push_str(&table_rule(number_width, right_width, '┼', settings.colorized));
        rendered.push('\n');
    } else if settings.style.has_header() {
        for header in &header_lines {
            rendered.push_str(header);
            rendered.push('\n');
        }
        if !header_lines.is_empty() {
            rendered.push('\n');
        }
    } else if settings.style.grid {
        rendered.push_str(&"─".repeat(settings.terminal_width));
        rendered.push('\n');
    }

    let highlight_set = build_highlight_set(&settings.highlight_ranges);
    let mut highlighter = syntax.zip(theme).map(|(syntax, theme)| HighlightLines::new(syntax, theme));

    for line in display_lines {
        if line.is_snip {
            if has_table {
                rendered.push_str(&format_snip_line(number_width, right_width, settings.colorized));
                rendered.push('\n');
            }
            continue;
        }

        let wrapped = wrap_content(&line.text, settings.wrap, content_width);
        if settings.number_override {
            for (index, piece) in wrapped.iter().enumerate() {
                let line_label = if index == 0 {
                    format!("{:>width$}", line.number, width = max(4, line_count_width))
                } else {
                    " ".repeat(max(4, line_count_width))
                };
                rendered.push_str(&format_number_only_line(
                    &line_label,
                    piece,
                    settings.colorized,
                    highlight_set.contains(&line.number),
                    &mut highlighter,
                ));
                if index < wrapped.len() - 1 || line.had_newline {
                    rendered.push('\n');
                }
            }
            continue;
        }

        if has_table {
            for (index, piece) in wrapped.iter().enumerate() {
                let numbered = if index == 0 {
                    Some(line.number)
                } else {
                    None
                };
                rendered.push_str(&format_table_line(
                    numbered,
                    line.marker,
                    piece,
                    settings,
                    content_width,
                    line_count_width,
                    highlight_set.contains(&line.number),
                    &mut highlighter,
                ));
                if index < wrapped.len() - 1 || line.had_newline {
                    rendered.push('\n');
                }
            }
        } else if settings.style.has_header() || settings.style.is_empty() || settings.plain_override {
            let colored = highlight_content_piece(
                &line.text,
                settings.colorized,
                highlight_set.contains(&line.number),
                content_width,
                &mut highlighter,
            );
            rendered.push_str(&colored);
            if line.had_newline {
                rendered.push('\n');
            }
        } else {
            rendered.push_str(&line.text);
            if line.had_newline {
                rendered.push('\n');
            }
        }
    }

    if has_table {
        rendered.push_str(&table_rule(number_width, right_width, '┴', settings.colorized));
        rendered.push('\n');
    } else if settings.style.grid {
        rendered.push_str(&"─".repeat(settings.terminal_width));
        rendered.push('\n');
    }

    rendered.into_bytes()
}

fn build_header_lines(source: &SourceData, settings: &Settings, is_binary: bool) -> Vec<String> {
    let mut headers = Vec::new();
    if settings.style.header_filename {
        let header = if source.is_stdin && settings.file_name_override.is_none() {
            "STDIN".to_owned()
        } else {
            format!("File: {}", source.label)
        };
        headers.push(header);
    }
    if settings.style.header_filesize {
        headers.push(format!("Size: {} B", source.bytes.len()));
    }
    if source.bytes.is_empty() && settings.style.header_filename {
        if let Some(first) = headers.first_mut() {
            first.push_str("   <EMPTY>");
        }
    } else if is_binary && settings.binary == BinaryBehavior::NoPrinting && settings.style.header_filename {
        if let Some(first) = headers.first_mut() {
            first.push_str("   <BINARY>");
        }
    }
    headers
}

fn render_header_only(source: &SourceData, settings: &Settings, tag: &str) -> Vec<u8> {
    let mut lines = build_header_lines(source, settings, true);
    if let Some(first) = lines.first_mut() {
        if !first.contains(tag) {
            first.push_str("   ");
            first.push_str(tag);
        }
    }
    let mut out = String::new();
    if settings.style.has_header() {
        for line in lines {
            out.push_str(&line);
            out.push('\n');
        }
        if !settings.style.grid {
            out.push('\n');
        }
    }
    out.into_bytes()
}

fn table_rule(left_width: usize, right_width: usize, separator: char, colorized: bool) -> String {
    let left = "─".repeat(left_width);
    let right = "─".repeat(right_width);
    let raw = format!("{left}{separator}{right}");
    if colorized {
        format!("{ANSI_GUTTER}{raw}{ANSI_RESET}")
    } else {
        raw
    }
}

fn format_table_header(left_width: usize, text: &str, colorized: bool) -> String {
    if colorized {
        format!(
            "{spaces}{ANSI_GUTTER}│ {ANSI_RESET}{}{}{}",
            if text.starts_with("File: ") {
                format!("File: \x1b[1m{}\x1b[0m", &text[6..])
            } else {
                text.to_owned()
            },
            "",
            "",
            spaces = " ".repeat(left_width),
        )
    } else {
        format!("{}│ {}", " ".repeat(left_width), text)
    }
}

fn wrap_header(text: &str, width: usize) -> Vec<String> {
    wrap_character(text, width.max(1))
}

fn build_highlight_set(ranges: &[ResolvedRange]) -> BTreeSet<usize> {
    let mut set = BTreeSet::new();
    for range in ranges {
        for number in range.start..=range.end {
            set.insert(number);
        }
    }
    set
}

fn format_number_only_line(
    line_label: &str,
    piece: &str,
    colorized: bool,
    highlighted: bool,
    highlighter: &mut Option<HighlightLines<'_>>,
) -> String {
    let label = if colorized {
        format!("{ANSI_GUTTER}{line_label}{ANSI_RESET}")
    } else {
        line_label.to_owned()
    };
    let content = highlight_content_piece(piece, colorized, highlighted, piece.width(), highlighter);
    format!("{label} {content}")
}

fn format_table_line(
    number: Option<usize>,
    marker: char,
    piece: &str,
    settings: &Settings,
    content_width: usize,
    line_count_width: usize,
    highlighted: bool,
    highlighter: &mut Option<HighlightLines<'_>>,
) -> String {
    let left_width = if settings.diff {
        max(4, line_count_width) + 3
    } else {
        max(4, line_count_width) + 1
    };
    let gutter_text = if let Some(number) = number {
        if settings.diff {
            format!(
                "{:>width$} {} ",
                number,
                marker,
                width = max(4, line_count_width)
            )
        } else {
            format!("{:>width$} ", number, width = max(4, line_count_width))
        }
    } else {
        " ".repeat(left_width)
    };

    let gutter = if settings.colorized {
        format!("{ANSI_GUTTER}{gutter_text}{ANSI_RESET}")
    } else {
        gutter_text
    };
    let separator = if settings.colorized {
        format!("{ANSI_GUTTER}│{ANSI_RESET}")
    } else {
        "│".to_owned()
    };
    let content = highlight_content_piece(piece, settings.colorized, highlighted, content_width, highlighter);
    format!("{gutter}{separator} {content}")
}

fn format_snip_line(left_width: usize, right_width: usize, colorized: bool) -> String {
    let fill = right_width.saturating_sub(1);
    let mut middle = String::new();
    while middle.width() + 3 < fill {
        middle.push_str("─ ");
    }
    middle.push_str("8<");
    while middle.width() + 2 <= fill {
        middle.push_str(" ─");
    }
    let left = " ... ".chars().take(left_width).collect::<String>();
    if colorized {
        format!("{ANSI_GUTTER}{left}{ANSI_RESET} {ANSI_GUTTER}│{ANSI_RESET} {middle}")
    } else {
        format!("{left}│ {middle}")
    }
}

fn wrap_content(text: &str, mode: WrapMode, width: usize) -> Vec<String> {
    match mode {
        WrapMode::Character => wrap_character(text, width.max(1)),
        WrapMode::Word => wrap_word(text, width.max(1)),
        _ => vec![text.to_owned()],
    }
}

fn wrap_character(text: &str, width: usize) -> Vec<String> {
    if width == 0 || text.width() <= width {
        return vec![text.to_owned()];
    }
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut current_width = 0usize;
    for ch in text.chars() {
        let ch_width = UnicodeWidthChar::width(ch).unwrap_or(1);
        if current_width + ch_width > width && !current.is_empty() {
            parts.push(current);
            current = String::new();
            current_width = 0;
        }
        current.push(ch);
        current_width += ch_width;
    }
    if !current.is_empty() {
        parts.push(current);
    }
    if parts.is_empty() {
        parts.push(String::new());
    }
    parts
}

fn wrap_word(text: &str, width: usize) -> Vec<String> {
    if width == 0 || text.width() <= width {
        return vec![text.to_owned()];
    }
    let mut lines = Vec::new();
    let mut current = String::new();
    for word in text.split(' ') {
        let candidate = if current.is_empty() {
            word.to_owned()
        } else {
            format!("{current} {word}")
        };
        if candidate.width() > width {
            if current.is_empty() {
                lines.extend(wrap_character(word, width));
            } else {
                lines.push(current);
                current = word.to_owned();
            }
        } else {
            current = candidate;
        }
    }
    if !current.is_empty() {
        lines.push(current);
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

fn highlight_content_piece(
    piece: &str,
    colorized: bool,
    highlighted: bool,
    content_width: usize,
    highlighter: &mut Option<HighlightLines<'_>>,
) -> String {
    let plain = if colorized {
        colorize_content(piece, highlighter)
    } else {
        piece.to_owned()
    };

    if !highlighted {
        return plain;
    }

    let padding = content_width.saturating_sub(piece.width());
    if colorized {
        format!(
            "{ANSI_HIGHLIGHT_BG}{plain}{ANSI_RESET}{ANSI_HIGHLIGHT_BG}{}{ANSI_RESET}",
            " ".repeat(padding)
        )
    } else {
        format!(
            "{ANSI_HIGHLIGHT_BG}{plain}{ANSI_RESET}{ANSI_HIGHLIGHT_BG}{}{ANSI_RESET}",
            " ".repeat(padding)
        )
    }
}

fn colorize_content(piece: &str, highlighter: &mut Option<HighlightLines<'_>>) -> String {
    if let Some(highlighter) = highlighter.as_mut() {
        if let Ok(regions) = highlighter.highlight_line(piece, &SyntaxSet::load_defaults_newlines()) {
            let mut out = String::new();
            for (style, text) in regions {
                out.push_str(&ansi_for_style(style));
                out.push_str(text);
                out.push_str(ANSI_RESET);
            }
            return out;
        }
    }
    format!("{ANSI_TEXT}{piece}{ANSI_RESET}")
}

fn ansi_for_style(style: Style) -> String {
    let fg = rgb_to_256(style.foreground.r, style.foreground.g, style.foreground.b);
    format!("\x1b[38;5;{fg}m")
}

fn rgb_to_256(r: u8, g: u8, b: u8) -> u8 {
    if r == g && g == b {
        if r < 8 {
            return 16;
        }
        if r > 248 {
            return 231;
        }
        return (((r as u16 - 8) / 10) + 232) as u8;
    }
    let r = ((r as f32 / 255.0) * 5.0).round() as u8;
    let g = ((g as f32 / 255.0) * 5.0).round() as u8;
    let b = ((b as f32 / 255.0) * 5.0).round() as u8;
    16 + 36 * r + 6 * g + b
}

fn load_theme() -> Option<Theme> {
    let themes = ThemeSet::load_defaults();
    themes
        .themes
        .get("base16-ocean.dark")
        .cloned()
        .or_else(|| themes.themes.values().next().cloned())
}

#[derive(Debug, Clone)]
struct DiffMarkerSet {
    keep_lines: BTreeSet<usize>,
    markers: std::collections::BTreeMap<usize, char>,
}

fn git_diff_markers(source: &SourceData, context: usize) -> Result<Option<DiffMarkerSet>, String> {
    let Some(path) = source.actual_path.as_ref() else {
        return Ok(Some(DiffMarkerSet {
            keep_lines: BTreeSet::new(),
            markers: Default::default(),
        }));
    };
    let parent = path.parent().unwrap_or_else(|| Path::new("."));
    let file_name = path.file_name().and_then(|name| name.to_str()).unwrap_or_default();
    let repo_check = Command::new("git")
        .arg("-C")
        .arg(parent)
        .args(["rev-parse", "--show-toplevel"])
        .output();
    let Ok(repo_check) = repo_check else {
        return Ok(Some(DiffMarkerSet {
            keep_lines: BTreeSet::new(),
            markers: Default::default(),
        }));
    };
    if !repo_check.status.success() {
        return Ok(Some(DiffMarkerSet {
            keep_lines: BTreeSet::new(),
            markers: Default::default(),
        }));
    }

    let output = Command::new("git")
        .arg("-C")
        .arg(parent)
        .args([
            "diff",
            "--no-ext-diff",
            "--no-color",
            &format!("-U{context}"),
            "--",
            file_name,
        ])
        .output()
        .map_err(|e| e.to_string())?;
    if !output.status.success() && output.stdout.is_empty() {
        return Ok(Some(DiffMarkerSet {
            keep_lines: BTreeSet::new(),
            markers: Default::default(),
        }));
    }
    let diff_text = String::from_utf8_lossy(&output.stdout);
    Ok(Some(parse_unified_diff(&diff_text)))
}

fn parse_unified_diff(text: &str) -> DiffMarkerSet {
    let mut keep_lines = BTreeSet::new();
    let mut markers = std::collections::BTreeMap::new();
    let mut current_new = 0usize;
    let mut in_hunk = false;
    let mut pending_block = Vec::<(char, String)>::new();
    let mut emitted_in_hunk = Vec::<usize>::new();
    let mut mark_next_overline = false;

    for line in text.lines() {
        if let Some(rest) = line.strip_prefix("@@") {
            finalize_diff_block(
                &mut pending_block,
                &mut current_new,
                &mut keep_lines,
                &mut markers,
                &mut emitted_in_hunk,
                &mut mark_next_overline,
            );
            in_hunk = true;
            emitted_in_hunk.clear();
            mark_next_overline = false;
            if let Some(new_part) = rest.split_whitespace().nth(1) {
                if let Some(new_range) = new_part.strip_prefix('+') {
                    let start = new_range
                        .split(',')
                        .next()
                        .unwrap_or("1")
                        .parse::<usize>()
                        .unwrap_or(1);
                    current_new = start;
                }
            }
            continue;
        }
        if !in_hunk {
            continue;
        }
        if line.starts_with("---") || line.starts_with("+++") {
            continue;
        }
        if line.starts_with('\\') {
            continue;
        }
        let prefix = line.chars().next().unwrap_or(' ');
        let content = line[1..].to_owned();
        if prefix == ' ' {
            finalize_diff_block(
                &mut pending_block,
                &mut current_new,
                &mut keep_lines,
                &mut markers,
                &mut emitted_in_hunk,
                &mut mark_next_overline,
            );
            keep_lines.insert(current_new);
            if mark_next_overline {
                markers.entry(current_new).or_insert('‾');
                mark_next_overline = false;
            }
            emitted_in_hunk.push(current_new);
            current_new += 1;
        } else if prefix == '+' || prefix == '-' {
            pending_block.push((prefix, content));
        }
    }

    finalize_diff_block(
        &mut pending_block,
        &mut current_new,
        &mut keep_lines,
        &mut markers,
        &mut emitted_in_hunk,
        &mut mark_next_overline,
    );

    DiffMarkerSet { keep_lines, markers }
}

fn finalize_diff_block(
    pending_block: &mut Vec<(char, String)>,
    current_new: &mut usize,
    keep_lines: &mut BTreeSet<usize>,
    markers: &mut std::collections::BTreeMap<usize, char>,
    emitted_in_hunk: &mut Vec<usize>,
    mark_next_overline: &mut bool,
) {
    if pending_block.is_empty() {
        return;
    }
    let plus_count = pending_block.iter().filter(|(kind, _)| *kind == '+').count();
    let minus_count = pending_block.iter().filter(|(kind, _)| *kind == '-').count();

    if plus_count > 0 && minus_count > 0 {
        for (kind, _) in pending_block.iter() {
            if *kind == '+' {
                keep_lines.insert(*current_new);
                markers.insert(*current_new, '~');
                emitted_in_hunk.push(*current_new);
                *current_new += 1;
            }
        }
    } else if plus_count > 0 {
        for (kind, _) in pending_block.iter() {
            if *kind == '+' {
                keep_lines.insert(*current_new);
                markers.insert(*current_new, '+');
                emitted_in_hunk.push(*current_new);
                *current_new += 1;
            }
        }
    } else if minus_count > 0 {
        if let Some(prev) = emitted_in_hunk.last().copied() {
            markers.entry(prev).or_insert('_');
        } else {
            *mark_next_overline = true;
        }
    }

    pending_block.clear();
}

fn apply_diff_filter(lines: Vec<RawLine>, markers: &DiffMarkerSet) -> Vec<RawLine> {
    lines.into_iter()
        .filter(|line| markers.keep_lines.contains(&line.number))
        .collect()
}

fn eprint_error(message: &str) {
    eprintln!("\x1b[31m[bat error]\x1b[0m: {message}");
}

fn eprint_warning(message: &str) {
    eprintln!("\x1b[33m[bat warning]\x1b[0m: {message}");
}
